from typing import TypeVar, Generic, Protocol, NewType, Literal, TypedDict, Sequence
from typing import Self

# ---- 1. Python 3.10+ 联合类型 ----
def process(value: int | str | None) -> str:
    if isinstance(value, int):
        return f"int: {value}"
    elif isinstance(value, str):
        return f"str: {value}"
    else:
        return "empty"

# ---- 2. TypedDict ----
class UserDict(TypedDict):
    name: str
    age: int
    email: str | None

user: UserDict = {"name": "Alice", "age": 30, "email": None}

# ---- 3. Literal 精确值 ----
Mode = Literal["r", "w", "a"]

def open_file(mode: Mode) -> None:
    pass

open_file("r")   # OK
# open_file("x") # mypy 报错: "x" 不是 Mode

# ---- 4. TypeVar 有界约束 ----
Number = TypeVar("Number", bound=int | float)

def sum_numbers(items: Sequence[Number]) -> Number:
    return sum(items)  # type: ignore[arg-type]

# ---- 5. NewType 语义区分 ----
UserId = NewType("UserId", int)
OrderId = NewType("OrderId", int)

def get_user(uid: UserId) -> str:
    return f"user_{uid}"

get_user(UserId(123))   # OK
# get_user(123)         # mypy: int 不是 UserId
# get_user(OrderId(1))  # mypy: OrderId 不是 UserId

# ---- 6. Protocol 结构化子类型 ----
class Drawable(Protocol):
    def draw(self) -> None: ...

class Circle:
    def draw(self) -> None:
        print("circle")

def render(obj: Drawable) -> None:
    obj.draw()

render(Circle())  # OK: Circle 隐式满足 Drawable

# ---- 7. Self 类型 (3.11+) ----
class Builder:
    def set_name(self, name: str) -> Self:
        self.name = name
        return self

    def set_age(self, age: int) -> Self:
        self.age = age
        return self
